'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Grid, Skeleton, Stack } from '@mui/material';
import AccountBalanceWalletRoundedIcon from '@mui/icons-material/AccountBalanceWalletRounded';
import LockRoundedIcon from '@mui/icons-material/LockRounded';
import ReceiptLongRoundedIcon from '@mui/icons-material/ReceiptLongRounded';
import { components } from '@/components';
import { data } from '@/data';
import { Routes } from '@/routes';
import { stores } from '@/stores';
import { HomeTab } from '@/stores/useTabStore';
import { EmptyState } from '@/components/invest/EmptyState';
import { InvestmentCard } from '@/components/invest/InvestmentCard';
import { MarketChip } from '@/components/invest/Badges';
import { StatTile } from '@/components/invest/StatTile';
import { LevelBadge } from '@/components/invest/LevelBadge';
import { useUserLevel } from '@/hooks/useUserLevel';
import { useMoney } from '@/hooks/useMoney';
import { Investment } from '@/types/InvestmentType';
import {
  accruedGain,
  expectedGain,
  isInvestmentActive,
} from '@/utils/invest_helper';

export const Portfolio: React.FC = () => {
  const router = useRouter();
  const { isLoggedIn, isLoadedCurrentUser, user } = stores.useUserStore();
  const { setTab } = stores.useTabStore();
  const [investments, setInvestments] = useState<Investment[] | null>(null);
  const [filter, setFilter] = useState<'active' | 'done'>('active');
  const { rank, level } = useUserLevel();
  const { formatAmount } = useMoney();

  useEffect(() => {
    if (!isLoggedIn) return;
    data
      .getInvestments()
      .then(setInvestments)
      .catch(() => setInvestments([]));
  }, [isLoggedIn, user?.investments?.length]);

  const header = (
    <components.Header title="Mon portefeuille" showBasket={true} />
  );

  if (isLoadedCurrentUser && !isLoggedIn) {
    return (
      <main className="container" style={{ paddingBottom: 30 }}>
        {header}
        <div style={{ marginTop: 20 }}>
          <EmptyState
            icon={<LockRoundedIcon sx={{ fontSize: 48 }} />}
            title="Connectez-vous pour voir votre portefeuille"
            description="Suivez vos investissements, vos gains et vos échéances en temps réel."
            actionLabel="Se connecter"
            onAction={() => router.push(Routes.SIGN_IN)}
          />
        </div>
      </main>
    );
  }

  const active = (investments ?? []).filter(isInvestmentActive);
  const done = (investments ?? []).filter((item) => !isInvestmentActive(item));
  const invested = active.reduce((acc, item) => acc + item.amount, 0);
  const gains = active.reduce((acc, item) => acc + accruedGain(item), 0);
  const expected = active.reduce(
    (acc, item) => acc + expectedGain(item.amount, item.expectedReturn),
    0,
  );
  const earned = done.reduce(
    (acc, item) => acc + expectedGain(item.amount, item.expectedReturn),
    0,
  );
  const list = filter === 'active' ? active : done;

  return (
    <main className="container" style={{ paddingBottom: 30 }}>
      {header}

      <div
        className="clickable"
        onClick={() => router.push(Routes.LEVELS)}
        style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8 }}
      >
        <LevelBadge rank={rank} level={level} size="medium" />
        <span
          className="t14"
          style={{ color: 'var(--main-color)', fontWeight: 600 }}
        >
          Voir ma progression →
        </span>
      </div>

      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 16,
          marginTop: 16,
          padding: 20,
          borderRadius: 24,
          background: 'linear-gradient(160deg, #1e2538 0%, #2b3554 100%)',
        }}
      >
        <div>
          <span className="t14" style={{ color: '#c8cdd9' }}>
            Solde disponible
          </span>
          <p
            style={{
              fontSize: 30,
              fontWeight: 800,
              color: '#fcc55e',
              lineHeight: 1.2,
            }}
          >
            {formatAmount(user?.availableBalance ?? 0)}
          </p>
        </div>
        <div style={{ textAlign: 'right' }}>
          <span className="t14" style={{ color: '#c8cdd9' }}>
            Actuellement investi
          </span>
          <p
            style={{
              fontSize: 22,
              fontWeight: 700,
              color: 'var(--white-color)',
            }}
          >
            {formatAmount(user?.activeBalance ?? invested)}
          </p>
        </div>
      </div>

      <Grid container spacing={2} sx={{ mt: 1, mb: 3 }}>
        {[
          {
            label: 'Capital investi',
            value: formatAmount(invested),
            hint: `${active.length} investissement${active.length > 1 ? 's' : ''} en cours`,
          },
          {
            label: 'Gains à ce jour',
            value: `+${formatAmount(gains)}`,
            color: 'var(--success-color)',
            hint: 'Calculés au prorata du temps écoulé',
          },
          {
            label: 'Gains attendus',
            value: `+${formatAmount(expected)}`,
            color: 'var(--success-color)',
            hint: 'À l’échéance des formules en cours',
          },
          {
            label: 'Gains déjà versés',
            value: formatAmount(earned),
            hint: `${done.length} investissement${done.length > 1 ? 's' : ''} terminé${done.length > 1 ? 's' : ''}`,
          },
        ].map((stat) => (
          <Grid key={stat.label} size={{ xs: 6, md: 3 }}>
            {investments === null ? (
              <Skeleton
                variant="rounded"
                height={110}
                sx={{ borderRadius: '20px' }}
              />
            ) : (
              <StatTile {...stat} />
            )}
          </Grid>
        ))}
      </Grid>

      <Stack
        direction="row"
        alignItems="center"
        justifyContent="space-between"
        flexWrap="wrap"
        gap={1}
        sx={{ mb: 2 }}
      >
        <Stack direction="row" gap={1}>
          <MarketChip
            label={`En cours (${active.length})`}
            active={filter === 'active'}
            onClick={() => setFilter('active')}
          />
          <MarketChip
            label={`Terminés (${done.length})`}
            active={filter === 'done'}
            onClick={() => setFilter('done')}
          />
        </Stack>
        <span
          className="t16 clickable"
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            color: 'var(--main-color)',
            fontWeight: 600,
          }}
          onClick={() => router.push(Routes.TRANSACTIONS)}
        >
          <ReceiptLongRoundedIcon sx={{ fontSize: 20 }} />
          Historique des transactions
        </span>
      </Stack>

      {investments === null ? (
        <Skeleton
          variant="rounded"
          height={180}
          sx={{ borderRadius: '24px' }}
        />
      ) : list.length === 0 ? (
        <EmptyState
          icon={<AccountBalanceWalletRoundedIcon sx={{ fontSize: 48 }} />}
          title={
            filter === 'active'
              ? 'Aucun investissement en cours'
              : 'Aucun investissement terminé'
          }
          description="Choisissez une maison de trading et une formule pour commencer à faire fructifier votre argent."
          actionLabel="Explorer les maisons"
          onAction={() => setTab(HomeTab.EXPLORE)}
        />
      ) : (
        <Grid container spacing={2}>
          {list.map((investment) => (
            <Grid key={investment.id} size={{ xs: 12, md: 6 }}>
              <InvestmentCard investment={investment} />
            </Grid>
          ))}
        </Grid>
      )}
    </main>
  );
};
