'use client';

import React, { useEffect } from 'react';
import { Box, Grid, Stack } from '@mui/material';
import HomeRoundedIcon from '@mui/icons-material/HomeRounded';
import TravelExploreRoundedIcon from '@mui/icons-material/TravelExploreRounded';
import AccountBalanceWalletRoundedIcon from '@mui/icons-material/AccountBalanceWalletRounded';
import PersonRoundedIcon from '@mui/icons-material/PersonRounded';
import { TabScreens } from '@/routes';
import { components } from '@/components';
import { stores } from '@/stores';
import { HomeTab } from '@/stores/useTabStore';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { TabItem } from '@/components/BottomTabBar';
import { TabIcon } from '@/components/invest/TabIcon';
import { AppLogo } from '@/components/invest/AppLogo';
import { InvestModal } from '@/components/invest/InvestModal';
import { WelcomeDialog } from '@/components/invest/WelcomeDialog';
import { APP_NAME } from '@/config';
import { Dashboard } from './Dashboard';
import { Explore } from '../explore/Explore';
import { Portfolio } from '../portfolio/Portfolio';
import { ProfilePage } from '../profile/Profile';

export const Home: React.FC = () => {
  const { isDesktop } = useDeviceDetect();
  const { currentTab, setTab, init } = stores.useTabStore();

  useEffect(() => {
    init();
  }, [init]);

  const pages: Record<HomeTab, React.ReactNode> = {
    [HomeTab.HOME]: <Dashboard />,
    [HomeTab.EXPLORE]: <Explore />,
    [HomeTab.PORTFOLIO]: <Portfolio />,
    [HomeTab.PROFILE]: <ProfilePage />,
  };

  const menu: TabItem[] = [
    { id: TabScreens.HOME, name: TabScreens.HOME, icon: HomeRoundedIcon },
    {
      id: TabScreens.EXPLORE,
      name: TabScreens.EXPLORE,
      icon: TravelExploreRoundedIcon,
    },
    {
      id: TabScreens.PORTFOLIO,
      name: TabScreens.PORTFOLIO,
      icon: AccountBalanceWalletRoundedIcon,
    },
    {
      id: TabScreens.PROFILE,
      name: TabScreens.PROFILE,
      icon: PersonRoundedIcon,
    },
  ].map((item, index) => ({
    ...item,
    icon: <TabIcon Icon={item.icon} active={currentTab === index} />,
  }));

  const renderSideBarMenu = () => (
    <Grid
      className="side-bar-menu"
      size={{ md: 2 }}
      style={{ padding: 0, margin: 0, height: '100vh' }}
    >
      <Stack
        direction="column"
        sx={{ padding: 0, margin: 0, width: '100%', height: '100%' }}
        alignItems="center"
        justifyContent="space-between"
      >
        <Box component="div" sx={{ my: 2, mx: 0, padding: 0, width: '100%' }}>
          <Stack direction="row" justifyContent="center">
            <AppLogo size={30} />
          </Stack>
          <components.SideBarMenu
            menuItems={menu}
            activeItem={currentTab}
            onChangeMenu={setTab}
          />
        </Box>
        <p className="t12" style={{ margin: 16 }}>
          Les performances passées ne préjugent pas des performances futures.
          Investir comporte un risque de perte en capital. © {APP_NAME}{' '}
          {new Date().getFullYear()}
        </p>
      </Stack>
    </Grid>
  );

  return (
    <components.Screen>
      <components.Background />
      {isDesktop ? (
        <Grid container spacing={0} style={{ padding: 0, margin: 0 }}>
          {renderSideBarMenu()}
          <Grid
            size={{ md: 10 }}
            style={{ padding: 0, margin: 0, height: '100vh', overflow: 'auto' }}
          >
            {pages[currentTab]}
          </Grid>
        </Grid>
      ) : (
        <>
          <div className="screen-content" style={{ paddingBottom: 90 }}>
            {pages[currentTab]}
          </div>
          <components.BottomTabBar
            tabs={menu}
            onChange={setTab}
            currentActive={currentTab}
          />
        </>
      )}
      <components.Modal />
      <InvestModal />
      <WelcomeDialog />
    </components.Screen>
  );
};
