'use client';

import { useEffect } from 'react';
import { stores } from '@/stores';

type Lockable = number | { canInvest?: boolean; requiredLevel?: number };

/** Palier courant de l'utilisateur (palier 1 pour un visiteur non connecté). */
export function useUserLevel() {
  const { user, isLoggedIn } = stores.useUserStore();
  const { levels, load } = stores.useLevelsStore();

  useEffect(() => {
    load();
  }, [load]);

  const rank = isLoggedIn ? (user?.levelRank ?? 1) : 1;
  const levelOf = (levelRank: number) =>
    levels.find((level) => level.rank === levelRank);

  const isLocked = (target: Lockable) => {
    if (typeof target === 'number') return target > rank;
    if (typeof target.canInvest === 'boolean') return !target.canInvest;
    return (target.requiredLevel ?? 1) > rank;
  };

  return {
    rank,
    level: levelOf(rank),
    levels,
    levelOf,
    isLocked,
  };
}
