'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { AssetImage as Image } from './AssetImage';
import { usePathname, useRouter } from 'next/navigation';
import {
  Alert,
  Badge,
  CircularProgress,
  Dialog,
  IconButton,
  Link,
  Paper,
  Stack,
} from '@mui/material';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import { Button } from '@/components/Button';
import { InputField } from '@/components/InputField';
import { OTPInput } from '@/components/OtpInput';
import { URLS_ASSETS } from '@/config';
import { servicesMobileMoney } from '@/constants/serviceMobileMoney';
import { data } from '@/data';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { Routes } from '@/routes';
import { stores } from '@/stores';
import { HomeTab } from '@/stores/useTabStore';
import { LocalStorageService } from '@/storages/local_storage_service';
import { primaryColor } from '@/styles/colors';
import { Investment } from '@/types/InvestmentType';
import {
  expectedGain,
  formatDate,
  formatDuration,
  formatInputAmount,
  formatPercent,
  parseInputAmount,
  STORAGE_CURRENCY,
} from '@/utils/invest_helper';
import { sortNotifications } from '@/utils/notification_helper';
import { MarketChip } from './Badges';
import { LevelBadge } from './LevelBadge';
import { useUserLevel } from '@/hooks/useUserLevel';
import { useMoney } from '@/hooks/useMoney';

type Step = 'form' | 'processing' | 'success';

const mobileMoneyServices = servicesMobileMoney.filter(
  (service) => service.type === 'mobile money',
);

const Row: React.FC<{ label: string; value: string; strong?: boolean }> = ({
  label,
  value,
  strong,
}) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
    <span className='t14'>{label}</span>
    <span
      style={{
        fontWeight: strong ? 700 : 500,
        color: strong ? 'var(--success-color)' : 'var(--main-color)',
        textAlign: 'right',
      }}
    >
      {value}
    </span>
  </div>
);

export const InvestModal: React.FC = () => {
  const router = useRouter();
  const pathname = usePathname();
  const { isDesktop } = useDeviceDetect();
  const { isOpen, house, planId, closeModal } = stores.useInvestModal();
  const { isLoggedIn, user, setUser } = stores.useUserStore();
  const { setNotifications } = stores.useNotificationStore();
  const { setTab } = stores.useTabStore();
  const { rank, isLocked, levelOf } = useUserLevel();
  const {
    code,
    digits,
    symbol,
    formatAmount,
    formatStorageAmount,
    toDisplay,
    toStorage,
  } = useMoney();

  const [step, setStep] = useState<Step>('form');
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');
  const [amount, setAmount] = useState<string>('');
  const [service, setService] = useState<string | null>(null);
  const [phone, setPhone] = useState<string>('');
  const [otp, setOtp] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [investment, setInvestment] = useState<Investment | null>(null);

  useEffect(() => {
    if (!isOpen || !house) return;
    const available = house.plans.filter((item) => !isLocked(item));
    const plan =
      available.find((item) => item.id === planId) ??
      available[0] ??
      house.plans[0];
    setStep('form');
    setSelectedPlanId(plan.id);
    setAmount(formatInputAmount(toDisplay(plan.minAmount), digits));
    setService(null);
    setPhone(user?.phone_number ?? '');
    setOtp('');
    setError('');
    setInvestment(null);
  }, [isOpen, house, planId, rank, digits, code]);

  const plan = useMemo(
    () => house?.plans.find((item) => item.id === selectedPlanId) ?? null,
    [house, selectedPlanId],
  );

  if (!house || !plan) return null;

  const numericDisplay = parseInputAmount(amount);
  const storageAmount = Math.round(toStorage(numericDisplay));
  const amountError =
    storageAmount < plan.minAmount || storageAmount > plan.maxAmount
      ? `Le montant doit être compris entre ${formatAmount(plan.minAmount)} et ${formatAmount(plan.maxAmount)}`
      : '';
  const serviceInfo = mobileMoneyServices.find((item) => item.name === service);
  const phoneError =
    phone.length > 1 &&
    serviceInfo?.startWith &&
    !phone.startsWith(serviceInfo.startWith)
      ? `Le numéro doit commencer par ${serviceInfo.startWith}`
      : phone.length > 0 && !/^\d{10}$/.test(phone)
        ? 'Le numéro doit contenir 10 chiffres'
        : '';
  const needsOtp = service === 'orangeci';
  const canSubmit =
    !amountError &&
    !!service &&
    phone.length === 10 &&
    !phoneError &&
    (!needsOtp || otp.length === 4);

  const gain = expectedGain(storageAmount, plan.expectedReturn);
  const endDate = new Date(
    Date.now() + plan.durationDays * 24 * 60 * 60 * 1000,
  );

  const hasAccess =
    !isLocked(house) && house.plans.some((item) => !isLocked(item));
  const houseLevel = levelOf(house.requiredLevel);

  const goToLevels = () => {
    closeModal();
    router.push(Routes.LEVELS);
  };

  const changePlan = (id: string) => {
    const next = house.plans.find((item) => item.id === id)!;
    setSelectedPlanId(id);
    if (
      storageAmount < next.minAmount ||
      storageAmount > next.maxAmount
    ) {
      setAmount(formatInputAmount(toDisplay(next.minAmount), digits));
    }
  };

  const goToSignIn = () => {
    LocalStorageService.saveLocationRedirection(pathname);
    closeModal();
    router.push(Routes.SIGN_IN);
  };

  const submit = async () => {
    setError('');
    setStep('processing');
    try {
      const response = await data.invest({
        houseId: house.id,
        planId: plan.id,
        amount: storageAmount,
        service: service!,
        numberTel: phone,
        otp: needsOtp ? otp : undefined,
      });
      if (!response.etat) {
        throw new Error(response.error?.[0] ?? 'Le paiement a échoué');
      }
      setInvestment(response.result.investment);
      const [freshUser, apiNotifications] = await Promise.all([
        data.getUser(),
        data.getNotifications().catch(() => null),
      ]);
      if (freshUser) {
        setUser(freshUser);
        setNotifications(
          sortNotifications(apiNotifications ?? freshUser.notifications ?? []),
        );
      }
      setStep('success');
    } catch (submitError) {
      setError(
        submitError instanceof Error
          ? submitError.message
          : 'Une erreur est survenue',
      );
      setStep('form');
    }
  };

  const goToPortfolio = () => {
    closeModal();
    setTab(HomeTab.PORTFOLIO);
    if (pathname !== Routes.HOME) router.push(Routes.HOME);
  };

  const renderHeader = () => (
    <Stack direction='row' alignItems='center' gap={1.5} sx={{ mb: 2 }}>
      <Image
        src={`${URLS_ASSETS.HOUSES}/${house.logo}`}
        alt={house.name}
        width={44}
        height={44}
        style={{ borderRadius: 12 }}
      />
      <div style={{ flex: 1 }}>
        <span className='t12'>Investir chez</span>
        <h4>{house.name}</h4>
      </div>
      <IconButton onClick={closeModal} aria-label='Fermer'>
        <CloseRoundedIcon />
      </IconButton>
    </Stack>
  );

  const renderNoAccess = () => (
    <Stack alignItems='center' gap={1.5} sx={{ py: 4, textAlign: 'center' }}>
      <LevelBadge
        rank={house.requiredLevel}
        level={houseLevel}
        locked
        size='medium'
      />
      <h4>
        Maison réservée au palier {houseLevel?.name ?? house.requiredLevel}
      </h4>
      <p className='t16'>
        {house.name} est accessible à partir du niveau{' '}
        {house.requiredLevelLabel || `palier ${house.requiredLevel}`}. Continuez
        à investir dans les formules de votre niveau pour progresser.
      </p>
      <Button
        label='Voir comment progresser'
        containerStyle={{ width: '100%', marginTop: 8 }}
        onClick={(event: React.MouseEvent) => {
          event.preventDefault();
          goToLevels();
        }}
      />
    </Stack>
  );

  const renderForm = () => (
    <>
      <h6 style={{ marginBottom: 8 }}>1. Choisissez une formule</h6>
      <div
        style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 20 }}
      >
        {house.plans.map((item) =>
          isLocked(item) ? (
            <span
              key={item.id}
              title={`Disponible : ${item.requiredLevelLabel || `palier ${item.requiredLevel}`}`}
              style={{ opacity: 0.55 }}
            >
              <MarketChip
                label={`🔒 ${item.name} · ${item.requiredLevelLabel || `palier ${item.requiredLevel}`}`}
              />
            </span>
          ) : (
            <MarketChip
              key={item.id}
              label={`${item.name} · ${formatPercent(item.expectedReturn, true)} / ${formatDuration(item.durationDays)}`}
              active={item.id === plan.id}
              onClick={() => changePlan(item.id)}
            />
          ),
        )}
      </div>

      <h6 style={{ marginBottom: 8 }}>2. Montant à investir ({symbol})</h6>
      <InputField
        value={amount}
        type='text'
        placeholder={formatInputAmount(toDisplay(plan.minAmount), digits)}
        onChange={(event) => {
          const raw = event.target.value;
          if (digits <= 0) {
            setAmount(raw.replace(/\D/g, ''));
            return;
          }
          const cleaned = raw.replace(/[^\d.,]/g, '');
          const [whole, ...rest] = cleaned.split(/[.,]/);
          setAmount(
            rest.length === 0
              ? cleaned.replace('.', ',')
              : `${whole},${rest.join('').slice(0, digits)}`,
          );
        }}
        containerStyle={{ marginBottom: 8 }}
      />
      <div
        style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 8 }}
      >
        {[
          plan.minAmount,
          Math.round((plan.minAmount + plan.maxAmount) / 2 / 1000) * 1000,
          plan.maxAmount,
        ].map((value) => (
          <MarketChip
            key={value}
            label={formatAmount(value)}
            active={storageAmount === value}
            onClick={() =>
              setAmount(formatInputAmount(toDisplay(value), digits))
            }
          />
        ))}
      </div>
      {amountError && amount.length > 0 && (
        <Alert severity='warning' sx={{ mb: 2 }}>
          {amountError}
        </Alert>
      )}

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 8,
          padding: 16,
          margin: '12px 0 20px',
          borderRadius: 20,
          backgroundColor: 'var(--white-color)',
          border: '1px solid var(--border-color)',
        }}
      >
        <Row
          label='Rendement prévu'
          value={`${formatPercent(plan.expectedReturn, true)} en ${formatDuration(plan.durationDays)}`}
        />
        <Row
          label='Gains estimés'
          value={`+${formatAmount(amountError ? 0 : gain)}`}
          strong
        />
        <Row
          label='Total à l’échéance'
          value={formatAmount(amountError ? 0 : storageAmount + gain)}
        />
        <Row label='Échéance' value={formatDate(endDate)} />
        <Row label='Versement des gains' value={plan.payout} />
      </div>

      {!isLoggedIn ? (
        <>
          <Alert severity='info' sx={{ mb: 2 }}>
            Connectez-vous avec votre numéro de téléphone pour finaliser votre
            investissement.
          </Alert>
          <Button
            label='Se connecter pour investir'
            onClick={(event: React.MouseEvent) => {
              event.preventDefault();
              goToSignIn();
            }}
          />
        </>
      ) : (
        <>
          <h6 style={{ marginBottom: 12 }}>3. Payez par mobile money</h6>
          <Stack direction='row' justifyContent='center' gap={2} sx={{ mb: 2 }}>
            {mobileMoneyServices.map((item) => (
              <Stack key={item.name} alignItems='center' gap={0.5}>
                <Badge
                  color='secondary'
                  overlap='circular'
                  variant='dot'
                  invisible={service !== item.name}
                >
                  <Paper
                    title={item.name}
                    elevation={service === item.name ? 8 : 2}
                    onClick={() => setService(item.name)}
                    sx={{
                      width: 52,
                      height: 52,
                      borderRadius: 40,
                      cursor: 'pointer',
                      outline:
                        service === item.name
                          ? `3px solid ${primaryColor}`
                          : 'none',
                      background: `center / cover no-repeat url("${item.flag}")`,
                    }}
                  />
                </Badge>
                <span className='t10'>{item.label}</span>
              </Stack>
            ))}
          </Stack>

          {service && (
            <>
              <InputField
                value={phone}
                onChange={(event) =>
                  setPhone(event.target.value.replace(/\D/g, '').slice(0, 10))
                }
                inputType='tel'
                type='tel'
                placeholder='Numéro à débiter (0XXXXXXXXX)'
                containerStyle={{ marginBottom: 12 }}
              />
              {phoneError && (
                <Alert severity='error' sx={{ mb: 2 }}>
                  {phoneError}
                </Alert>
              )}
              {needsOtp && !phoneError && (
                <div style={{ marginBottom: 12 }}>
                  <p className='t14' style={{ marginBottom: 8 }}>
                    Composez le{' '}
                    <Link href='tel:#144*82#' sx={{ color: primaryColor }}>
                      #144*82#
                    </Link>{' '}
                    pour obtenir votre code de paiement Orange Money, puis
                    saisissez-le ci-dessous.
                  </p>
                  <Stack direction='row' justifyContent='center'>
                    <OTPInput length={4} value={otp} onChange={setOtp} />
                  </Stack>
                </div>
              )}
            </>
          )}

          {error && (
            <Alert severity='error' sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          <Button
            label={`Investir ${amountError ? '' : formatAmount(storageAmount)}`}
            disabled={!canSubmit}
            onClick={(event: React.MouseEvent) => {
              event.preventDefault();
              if (canSubmit) submit();
            }}
          />
          <p className='t12' style={{ marginTop: 12, textAlign: 'center' }}>
            Les performances passées ne préjugent pas des performances futures.
            Investir comporte un risque de perte en capital.
          </p>
        </>
      )}
    </>
  );

  const renderProcessing = () => (
    <Stack
      alignItems='center'
      justifyContent='center'
      gap={2}
      sx={{ py: 8, textAlign: 'center' }}
    >
      <CircularProgress sx={{ color: 'var(--accent-color)' }} />
      <h4>Paiement en cours…</h4>
      <p className='t16'>
        Validez le paiement de {formatStorageAmount(storageAmount)}
        {code !== STORAGE_CURRENCY ? ` (${formatAmount(storageAmount)})` : ''}{' '}
        sur votre téléphone {phone}.
      </p>
    </Stack>
  );

  const renderSuccess = () => (
    <Stack alignItems='center' gap={1.5} sx={{ py: 3, textAlign: 'center' }}>
      <CheckCircleRoundedIcon
        sx={{ fontSize: 72, color: 'var(--success-color)' }}
      />
      <h3 style={{ fontWeight: 700 }}>Investissement confirmé !</h3>
      <p className='t16'>
        Vous avez investi {formatAmount(investment?.amount ?? storageAmount)}{' '}
        dans la formule {plan.name} de {house.name}.
      </p>
      <div
        style={{
          width: '100%',
          display: 'flex',
          flexDirection: 'column',
          gap: 8,
          padding: 16,
          margin: '8px 0 12px',
          borderRadius: 20,
          backgroundColor: 'var(--white-color)',
          border: '1px solid var(--border-color)',
        }}
      >
        <Row label='Gains estimés' value={`+${formatAmount(gain)}`} strong />
        <Row
          label='Total à l’échéance'
          value={formatAmount(storageAmount + gain)}
        />
        <Row
          label='Échéance'
          value={formatDate(investment?.endDate ?? endDate)}
        />
      </div>
      <Button
        label='Voir mon portefeuille'
        containerStyle={{ width: '100%' }}
        onClick={(event: React.MouseEvent) => {
          event.preventDefault();
          goToPortfolio();
        }}
      />
      <Button
        label='Fermer'
        colorScheme='secondary'
        containerStyle={{ width: '100%' }}
        onClick={(event: React.MouseEvent) => {
          event.preventDefault();
          closeModal();
        }}
      />
    </Stack>
  );

  return (
    <Dialog
      open={isOpen}
      onClose={step === 'processing' ? undefined : closeModal}
      fullScreen={!isDesktop}
      maxWidth='sm'
      fullWidth
      slotProps={{
        paper: {
          sx: {
            backgroundColor: '#F5FAFB',
            borderRadius: isDesktop ? '28px' : 0,
          },
        },
      }}
    >
      <div style={{ padding: 24 }}>
        {renderHeader()}
        {step === 'form' && (hasAccess ? renderForm() : renderNoAccess())}
        {step === 'processing' && renderProcessing()}
        {step === 'success' && renderSuccess()}
      </div>
    </Dialog>
  );
};
